import { CliExit } from './errors.mjs';

const OPTION_NAMES = ['--a', '--b'];
const OPTION_KEYS = {
  '--a': 'a',
  '--b': 'b',
};

function buildUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B`;
}

function buildHelp(programName) {
  return `${buildUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n`;
}

function buildError(programName, message) {
  return `${buildUsage(programName)}\n${programName}: error: ${message}\n`;
}

function isOptionToken(token) {
  return token.startsWith('-') && token !== '-';
}

function getAttachedOption(token) {
  for (const optionName of OPTION_NAMES) {
    const prefix = `${optionName}=`;
    if (token.startsWith(prefix)) {
      return {
        optionName,
        value: token.slice(prefix.length),
      };
    }
  }

  return null;
}

export function parseTest9Args(argv, programName) {
  if (argv.includes('-h') || argv.includes('--help')) {
    throw new CliExit(0, buildHelp(programName), 'stdout');
  }

  const values = {
    a: undefined,
    b: undefined,
  };
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (Object.hasOwn(OPTION_KEYS, token)) {
      const nextToken = argv[index + 1];
      if (nextToken === undefined || isOptionToken(nextToken)) {
        throw new CliExit(
          2,
          buildError(programName, `argument ${token}: expected one argument`),
          'stderr',
        );
      }

      values[OPTION_KEYS[token]] = nextToken;
      index += 1;
      continue;
    }

    const attachedOption = getAttachedOption(token);
    if (attachedOption !== null) {
      values[OPTION_KEYS[attachedOption.optionName]] = attachedOption.value;
      continue;
    }

    extras.push(token);
  }

  const missing = OPTION_NAMES.filter((optionName) => values[OPTION_KEYS[optionName]] === undefined);
  if (missing.length > 0) {
    throw new CliExit(
      2,
      buildError(programName, `the following arguments are required: ${missing.join(', ')}`),
      'stderr',
    );
  }

  if (extras.length > 0) {
    throw new CliExit(
      2,
      buildError(programName, `unrecognized arguments: ${extras.join(' ')}`),
      'stderr',
    );
  }

  return values;
}

